#[cfg(test)]
mod merge_tree_cache_tests {
    use super::*;
    use crate::testing::TestRepo;

    /// The conflict probe ([`Repository::has_merge_conflicts_by_sha`], driving
    /// the `WouldConflict` column) and the integration probe
    /// ([`Repository::merge_integration_probe_by_sha`], driving the
    /// integration column) both run `git merge-tree --write-tree <target>
    /// <branch>` for the same row but extract different answers — the conflict
    /// bit versus the resulting tree. They must key the in-memory cache
    /// identically, in `(target, branch)` order, so the subprocess fires once
    /// per row rather than once per probe. An argument-order regression on
    /// either call site would split this into two entries (two spawns); this
    /// pins it at one.
    #[test]
    fn conflict_and_integration_probes_share_one_merge_tree_spawn() {
        let test = TestRepo::with_initial_commit();

        // feature: one commit ahead of main, clean-mergeable, not integrated.
        test.run_git(&["checkout", "-b", "feature"]);
        std::fs::write(test.root_path().join("new.txt"), "content\n").unwrap();
        test.run_git(&["add", "new.txt"]);
        test.run_git(&["commit", "-m", "feature"]);
        test.run_git(&["checkout", "main"]);

        let main_sha = test.git_output(&["rev-parse", "main"]);
        let feature_sha = test.git_output(&["rev-parse", "feature"]);

        let repo = Repository::at(test.root_path()).unwrap();

        // Conflict probe: a clean merge has no conflicts.
        assert!(
            !repo
                .has_merge_conflicts_by_sha(&main_sha, &feature_sha)
                .unwrap()
        );
        // Integration probe: merging adds new.txt, so it would change main —
        // not yet integrated, and no patch-id fallback (merge was clean).
        let probe = repo
            .merge_integration_probe_by_sha(&feature_sha, &main_sha)
            .unwrap();
        assert!(probe.would_merge_add);
        assert!(!probe.is_patch_id_match);

        // Both probes resolved through a single shared merge-tree entry, keyed
        // (target, branch) = (main, feature).
        assert_eq!(
            repo.cache.merge_tree.len(),
            1,
            "conflict + integration probes must share one merge-tree cache entry"
        );
        assert!(
            repo.cache.merge_tree.contains_key(&(main_sha, feature_sha)),
            "the shared entry must be keyed (target, branch)"
        );
    }

    /// A merge-tree probe mid-merge-driver must not be signalled when the
    /// picker cancels background work: git removes the driver's
    /// `.merge_file_*` temp files only on a normal return, so a SIGTERM strands
    /// them in the worktree (#4273). The driver records its parent — the
    /// running `git merge-tree` — so the test can check that PID isn't
    /// registered for cancellation while the driver runs.
    #[cfg(unix)]
    #[test]
    fn merge_tree_probe_is_not_signalled_on_cancel() {
        let test = TestRepo::with_initial_commit();
        let root = test.root_path().to_path_buf();
        std::fs::write(root.join("f.txt"), "a\nb\nc\n").unwrap();
        test.run_git(&["add", "f.txt"]);
        test.run_git(&["commit", "-m", "base"]);
        test.run_git(&["checkout", "-b", "feature"]);
        std::fs::write(root.join("f.txt"), "a\nFEAT\nc\n").unwrap();
        test.run_git(&["commit", "-am", "feature"]);
        test.run_git(&["checkout", "main"]);
        std::fs::write(root.join("f.txt"), "a\nMAIN\nc\n").unwrap();
        test.run_git(&["commit", "-am", "main"]);
        let main_sha = test.git_output(&["rev-parse", "main"]);
        let feature_sha = test.git_output(&["rev-parse", "feature"]);

        let dir = crate::testing::test_tempdir();
        let marker = dir.path().join("driver-parent");
        let release = dir.path().join("release");
        let driver = format!(
            "echo $PPID > '{}'; while [ ! -e '{}' ]; do sleep 0.05; done; exit 1",
            marker.display(),
            release.display()
        );
        test.run_git(&["config", "merge.slow.driver", &driver]);
        let git_dir = test.git_output(&["rev-parse", "--absolute-git-dir"]);
        std::fs::create_dir_all(std::path::Path::new(&git_dir).join("info")).unwrap();
        std::fs::write(
            std::path::Path::new(&git_dir).join("info/attributes"),
            "* merge=slow\n",
        )
        .unwrap();

        let repo = Repository::at(&root).unwrap();
        std::thread::scope(|s| {
            let probe = s.spawn(|| repo.merge_tree_outcome(&main_sha, &feature_sha));
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
            let pid = loop {
                if let Some(pid) = std::fs::read_to_string(&marker)
                    .ok()
                    .and_then(|s| s.trim().parse::<u32>().ok())
                {
                    break pid;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "merge driver never ran"
                );
                std::thread::sleep(std::time::Duration::from_millis(20));
            };
            let cancellable = crate::shell_exec::is_cancellable_pid(pid);
            std::fs::write(&release, "").unwrap();
            let outcome = probe.join().unwrap().unwrap();
            assert!(
                !cancellable,
                "a running merge-tree must not be a cancellation target"
            );
            assert!(matches!(outcome, MergeTreeOutcome::Conflict));
        });
    }
}

#[cfg(test)]
mod read_only_object_store_tests {
    use super::*;
    use crate::testing::TestRepo;

    /// A cleanly-mergeable but diverged topology: `main` and `feature` touch
    /// different files off a shared base, so `merge-tree --write-tree` must
    /// write a genuinely new tree (not a fast-forward that reuses an existing
    /// one). Returns `(main_sha, feature_sha)`.
    fn diverged_repo() -> (TestRepo, String, String) {
        let test = TestRepo::with_initial_commit();
        test.run_git(&["checkout", "-b", "feature"]);
        std::fs::write(test.root_path().join("feature.txt"), "feature\n").unwrap();
        test.run_git(&["add", "feature.txt"]);
        test.run_git(&["commit", "-m", "feature"]);
        test.run_git(&["checkout", "main"]);
        std::fs::write(test.root_path().join("main.txt"), "main\n").unwrap();
        test.run_git(&["add", "main.txt"]);
        test.run_git(&["commit", "-m", "main"]);
        let main_sha = test.git_output(&["rev-parse", "main"]);
        let feature_sha = test.git_output(&["rev-parse", "feature"]);
        (test, main_sha, feature_sha)
    }

    #[cfg(unix)]
    #[test]
    fn redirected_objects_resolve_a_repo_path_containing_a_colon() {
        let parent = crate::testing::test_tempdir();
        let test = TestRepo::at(&parent.path().join("repo:with-colon"));
        test.commit("Initial commit");

        let redirected = test.repo.redirect_objects_for_observation().unwrap();
        assert!(
            redirected
                .run_command_check(&["cat-file", "-e", "HEAD"])
                .unwrap(),
            "the real object database must remain readable through the redirect"
        );
    }

    #[cfg(unix)]
    #[test]
    fn redirected_objects_resolve_a_repo_path_containing_a_newline() {
        let parent = crate::testing::test_tempdir();
        let test = TestRepo::at(&parent.path().join("repo\nwith-newline"));
        test.commit("Initial commit");

        let redirected = test.repo.redirect_objects_for_observation().unwrap();
        assert!(
            redirected
                .run_command_check(&["cat-file", "-e", "HEAD"])
                .unwrap(),
            "the real object database must remain readable through the redirect"
        );
    }

    #[test]
    fn redirected_object_directory_unregisters_on_drop() {
        let test = TestRepo::with_initial_commit();
        let redirected = test.repo.redirect_objects_for_observation().unwrap();
        let directory = redirected
            .object_store_environment()
            .unwrap()
            .0
            .to_path_buf();
        assert!(
            test.repo
                .cache
                .observation_object_directories
                .contains_key(&directory)
        );

        drop(redirected);

        assert!(
            !test
                .repo
                .cache
                .observation_object_directories
                .contains_key(&directory)
        );
        assert!(!directory.exists());
    }

    /// The safety property behind scoping the redirect to observational
    /// commands: a redirected merge tree is computed correctly but written only
    /// to the throwaway store, so it is *not* in the real object database. A
    /// mutating command that redirected would therefore lose its commit — which
    /// is why mutating commands keep the persistent path and fail loudly on a
    /// read-only store instead.
    #[test]
    fn redirected_object_writes_stay_out_of_the_real_database() {
        let (test, main_sha, feature_sha) = diverged_repo();
        let merge_tree = |repo: &Repository| {
            repo.run_command(&["merge-tree", "--write-tree", &main_sha, &feature_sha])
                .unwrap()
                .lines()
                .next()
                .unwrap()
                .trim()
                .to_string()
        };

        // Redirected clone: the merge tree lands in the temporary store only.
        let redirected = Repository::at(test.root_path())
            .unwrap()
            .redirect_objects_for_observation()
            .unwrap();
        let ephemeral_tree = merge_tree(&redirected);

        // A separate, non-redirected repository reads the real database
        // directly; the redirected tree is absent there.
        let real = Repository::at(test.root_path()).unwrap();
        assert!(
            !real
                .run_command_check(&["cat-file", "-e", &ephemeral_tree])
                .unwrap(),
            "a redirected merge tree must not be written to the real object database"
        );

        // The persistent path yields the same content-addressed tree, this time
        // materialized in the real database.
        let persistent_tree = merge_tree(&real);
        assert_eq!(persistent_tree, ephemeral_tree);
        assert!(
            real.run_command_check(&["cat-file", "-e", &persistent_tree])
                .unwrap(),
            "the persistent path must materialize its merge tree in the real database"
        );
    }
}

use crate::common::{BareRepoTest, TestRepo, TestRepoBase, repo, repo_with_remote};
use rstest::rstest;
use std::fs;
use worktrunk::git::{GitRemoteUrl, Repository};

#[rstest]
fn test_get_default_branch_with_origin_head(#[from(repo_with_remote)] repo: TestRepo) {
    // origin/HEAD should be set automatically by setup_remote
    assert!(repo.has_origin_head());

    // Test that we can get the default branch
    let branch = Repository::at(repo.root_path())
        .unwrap()
        .default_branch()
        .unwrap();
    assert_eq!(branch, "main");
}

#[rstest]
fn test_get_default_branch_without_origin_head(#[from(repo_with_remote)] repo: TestRepo) {
    // Clear origin/HEAD to force remote query
    repo.clear_origin_head();
    assert!(!repo.has_origin_head());

    // Should still work by querying remote
    let branch = Repository::at(repo.root_path())
        .unwrap()
        .default_branch()
        .unwrap();
    assert_eq!(branch, "main");

    // Verify that worktrunk's cache is now set
    let cached = repo
        .git_command()
        .args(["config", "--get", "worktrunk.default-branch"])
        .run()
        .unwrap();
    assert_eq!(String::from_utf8_lossy(&cached.stdout).trim(), "main");
}

#[rstest]
fn test_get_default_branch_caches_result(#[from(repo_with_remote)] repo: TestRepo) {
    // Clear both caches to force remote query
    repo.clear_origin_head();
    let _ = repo
        .git_command()
        .args(["config", "--unset", "worktrunk.default-branch"])
        .run();

    // First call queries remote and caches to worktrunk config
    Repository::at(repo.root_path())
        .unwrap()
        .default_branch()
        .unwrap();
    let cached = repo
        .git_command()
        .args(["config", "--get", "worktrunk.default-branch"])
        .run()
        .unwrap();
    assert!(cached.status.success());

    // Second call uses cache (fast path)
    let branch = Repository::at(repo.root_path())
        .unwrap()
        .default_branch()
        .unwrap();
    assert_eq!(branch, "main");
}

/// A remote that never answers is bounded, and the fallback it forces is not
/// persisted. `ls-remote` has no timeout of its own — an unreachable host costs
/// ~127 s per address on Linux — so detection gives up after
/// `REMOTE_DETECTION_TIMEOUT` and infers from local branches instead. It must
/// not write that inference to `worktrunk.default-branch`: the persisted cache
/// is what stops later calls from re-detecting, so a guess made during an
/// outage would become the repo's permanent answer.
///
/// The stall is reproduced without touching the network — `origin` is a local
/// path whose `uploadpack` command never returns. The bound under test is
/// platform-independent; only this vehicle needs a POSIX `sleep`.
#[rstest]
#[cfg(unix)]
fn test_default_branch_unreachable_remote_is_bounded_and_not_cached(
    #[from(repo_with_remote)] repo: TestRepo,
) {
    repo.clear_origin_head();
    let _ = repo
        .git_command()
        .args(["config", "--unset", "worktrunk.default-branch"])
        .run();
    // `sh -c '…'` rather than a bare `sleep`: git appends the repository path,
    // which `sleep` would reject as a second interval but `sh` takes as `$0`.
    repo.run_git(&["config", "remote.origin.uploadpack", "sh -c 'sleep 120'"]);

    let start = std::time::Instant::now();
    let branch = Repository::at(repo.root_path()).unwrap().default_branch();
    let elapsed = start.elapsed();

    assert_eq!(
        branch.as_deref(),
        Some("main"),
        "local inference must still answer while the remote hangs"
    );
    assert!(
        elapsed < std::time::Duration::from_secs(60),
        "ls-remote was not bounded: took {elapsed:?}"
    );

    let cached = repo
        .git_command()
        .args(["config", "--get", "worktrunk.default-branch"])
        .run()
        .unwrap();
    assert!(
        !cached.status.success(),
        "a timed-out detection must not be cached, got {:?}",
        String::from_utf8_lossy(&cached.stdout).trim()
    );
}

/// A remote that fails fast — a deleted upstream, an offline laptop — falls
/// back to local inference too, and that answer *is* cached. `ls-remote` exits
/// 128 whether the network is down or the remote simply has no HEAD, so the
/// two aren't separable without reading git's error text, and re-querying on
/// every command is what the cache exists to avoid.
#[rstest]
fn test_default_branch_unresolvable_remote_falls_back_and_caches(
    #[from(repo_with_remote)] repo: TestRepo,
) {
    repo.clear_origin_head();
    let _ = repo
        .git_command()
        .args(["config", "--unset", "worktrunk.default-branch"])
        .run();
    let gone = repo.root_path().join("no-such-remote");
    repo.run_git(&["config", "remote.origin.url", &gone.to_string_lossy()]);

    let branch = Repository::at(repo.root_path()).unwrap().default_branch();
    assert_eq!(branch.as_deref(), Some("main"));

    let cached = repo
        .git_command()
        .args(["config", "--get", "worktrunk.default-branch"])
        .run()
        .unwrap();
    assert_eq!(String::from_utf8_lossy(&cached.stdout).trim(), "main");
}

#[rstest]
fn test_get_default_branch_no_remote(repo: TestRepo) {
    // Remove origin (fixture has it) for this no-remote test
    repo.run_git(&["remote", "remove", "origin"]);

    // No remote configured, should infer from local branches
    // Since there's only one local branch, it should return that
